sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	if (current.default_min_zoom && (current.default_min_zoom < 10 || current.default_min_zoom > 23)) {
		current.setAbortAction(true);
		gs.addErrorMessage(gs.getMessage('Default minimum zoom field must be between {0} and {1}', [10, 23]));
	}

	if (current.default_max_zoom && (current.default_max_zoom < 10 || current.default_max_zoom > 23)) {
		current.setAbortAction(true);
		gs.addErrorMessage(gs.getMessage('Default maximum zoom field must be between {0} and {1}', [10, 23]));
	}

	if (current.default_max_zoom && current.default_min_zoom && current.default_max_zoom < current.default_min_zoom) {
		current.setAbortAction(true);
		gs.addErrorMessage(gs.getMessage('Default maximum zoom field must be greater than default minimum zoom field'));
	}

	if (current.default_order && current.default_order < 0) {
		current.setAbortAction(true);
		gs.addErrorMessage(gs.getMessage('Default order field must not be a negative number'));
	}

	if (current.default_wait_time && current.default_wait_time < 0) {
		current.setAbortAction(true);
		gs.addErrorMessage(gs.getMessage('Default wait time field must not be a negative number'));
	}

	if (current.default_time_per_floor && current.default_time_per_floor < 0) {
		current.setAbortAction(true);
		gs.addErrorMessage(gs.getMessage('Default time per floor field must not be a negative number'));
	}

})(current, previous);
